<?php require __DIR__.'/../bootstrap.php';admin_only();verify_csrf();if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM products WHERE id=?')->execute([(int)$_GET['delete']]);flash('ok','محصول حذف شد.');redirect('admin/products.php');}$products=$pdo->query('SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll();$title='مدیریت محصولات';require __DIR__.'/../partials/header.php';?><div class="section-head"><h1>محصولات</h1><a class="btn" href="<?=url('admin/product_form.php')?>">+ محصول جدید</a></div><div class="panel table-wrap"><table class="table"><tr><th>ID</th><th>نام</th><th>دسته</th><th>قیمت</th><th>موجودی</th><th>فروش</th><th>فعال</th><th></th></tr><?php foreach($products as $p): ?><tr><td><?=$p['id']?></td><td><?=e($p['name'])?></td><td><?=e($p['category']??'-')?></td><td><?=money($p['price'])?></td><td><?=$p['stock']?></td><td><?=$p['sales']?></td><td><?=$p['active']?'✅':'⛔'?></td><td><a class="btn small" href="<?=url('admin/product_form.php?id='.$p['id'])?>">ویرایش</a> <a class="btn red small" data-confirm="حذف شود؟" href="<?=url('admin/products.php?delete='.$p['id'])?>">حذف</a></td></tr><?php endforeach; ?></table></div><?php require __DIR__.'/../partials/footer.php'; ?>
